policy.text:
// exonumia x402 rail: the client's limit as the hunt reads a cap (card X2a).

@id("pay_cap")
permit (
    principal,
    action == Kamanu::Action::"Pay",
    resource
)
when temporal {
    (sum a for (a: Long), (t: Timepoint). where (
        formerly within 1m (Kamanu::Action::"Pay"::request{ input.amount: a } && tp(t))
    )) <= 1000
};
